#!/usr/bin/env bash
#
# canectic-pm2 -- launch pm2 under the right Node, whether that Node came from
# nvm or from the OS package manager.
#
# Why this exists: the unit generated by `pm2 startup` bakes an absolute Node
# path into both PATH and ExecStart:
#
#   Environment=PATH=/home/you/.nvm/versions/node/v26.8.1/bin:...
#   ExecStart=/home/you/.nvm/versions/node/v26.8.1/lib/node_modules/pm2/bin/pm2 resurrect
#
# On an nvm box that silently pins the service to whichever Node was current the
# day the unit was generated, and the BBS stops booting once that version is
# removed. A BBS is expected to stay up for years across several OS upgrades, so
# the boot path should not need editing every time Node moves.
#
# Resolution order:
#   1. nvm, following the `default` alias, if $NVM_DIR/nvm.sh is present
#   2. pm2 already on PATH (distro or manually installed Node)
# Either way the version choice is made at start time, not frozen into the unit.
#
# Install outside the repo, since update.sh wipes and recopies setup/:
#   install -m 755 setup/canectic-pm2.sh ~/.local/bin/canectic-pm2
#
# Arguments pass straight through to pm2, so one wrapper serves every Exec*
# line. See docs/sysop/INSTALL.md, "Surviving Node Upgrades".

# Set by the unit so this does not depend on systemd exporting HOME. The
# fallback covers interactive use and native-Node boxes where it is unset.
export NVM_DIR="${NVM_DIR:-$HOME/.nvm}"

if [ -s "$NVM_DIR/nvm.sh" ]; then
	# --no-use loads nvm's shell functions without selecting a version, so the
	# choice below is explicit rather than inherited from the environment.
	# Deliberately no `set -e`/`set -u` here: nvm.sh is a large script that is
	# not written to survive strict mode being active while it is sourced.
	# shellcheck source=/dev/null
	. "$NVM_DIR/nvm.sh" --no-use

	if ! nvm use --silent default >/dev/null 2>&1; then
		# nvm is installed but has no usable default. Rather than dying, fall
		# through to whatever Node is on PATH so a half-configured nvm cannot
		# keep the BBS from booting.
		echo "canectic-pm2: nvm found but 'nvm use default' failed; falling back to PATH." \
		     "Set one with: nvm alias default <version>" >&2
	fi
fi

if ! command -v pm2 >/dev/null 2>&1; then
	echo "canectic-pm2: pm2 not found for $(node -v 2>/dev/null || echo 'no node on PATH')." >&2
	echo "canectic-pm2: pm2 installs per Node version, so a new Node needs its own: npm install -g pm2" >&2
	exit 1
fi

exec pm2 "$@"
